//static.wikia.nocookie.net/bee-swarm-simulator/images/f/fa/Bubble_Bee.png/revision/latest?cb=20200403235509","https://static.wikia.nocookie.net/bee-swarm-simulator/images/4/41/BuckoFace.png/revision/latest?cb=20230507154530","https://static.wikia.nocookie.net/bee-swarm-simulator/images/9/94/Tadpole_Bee_Face.png/revision/latest/scale-to-width-down/220?cb=20230227085930","https://static.wikia.nocookie.net/bee-swarm-simulator/images/d/dc/Buoyant_Face.png/revision/latest/scale-to-width-down/220?cb=20230227091123"],F=["https://static.wikia.nocookie.net/bee-swarm-simulator/images/8/83/BasicIcon.png/revision/latest?cb=20230506115759","https://static.wikia.nocookie.net/bee-swarm-simulator/images/1/18/LookerIcon.png/revision/latest?cb=20230507144422","https://static.wikia.nocookie.net/bee-swarm-simulator/images/0/0e/Commander_Bee.png/revision/latest?cb=20200403235837","https://static.wikia.nocookie.net/bee-swarm-simulator/images/2/26/Vector_Bee_Face.png/revision/latest/scale-to-width-down/220?cb=20230227090717","https://static.wikia.nocookie.net/bee-swarm-simulator/images/a/a5/FuzzyBeeFace.png/revision/latest?cb=20230227090920"],P=["https://static.wikia.nocookie.net/bee-swarm-simulator/images/7/7b/Rage_Bee.png/revision/latest?cb=20200404000023","https://static.wikia.nocookie.net/bee-swarm-simulator/images/1/14/Firefaceoriginal.png/revision/latest?cb=20230227075732","https://static.wikia.nocookie.net/bee-swarm-simulator/images/6/64/Riley_Bee.png/revision/latest?cb=20200404000004","https://static.wikia.nocookie.net/bee-swarm-simulator/images/a/ae/Spicy_Bee_Face.png/revision/latest/scale-to-width-down/220?cb=20230227090647","https://static.wikia.nocookie.net/bee-swarm-simulator/images/5/56/Precise_Bee_Face.png/revision/latest/scale-to-width-down/220?cb=20230227090816"],ee=[{name:"Blue Hive",color:"blue",href:"#blue-hive",icon:"https://static.wikia.nocookie.net/bee-swarm-simulator/images/7/75/Diamond_Mask.png/revision/latest/scale-to-width-down/406?cb=20190403022722",bees:E,tools:[{name:"Tide Popper",image:"https://static.wikia.nocookie.net/bee-swarm-simulator/images/c/cc/Tide_Popper.png/revision/latest?cb=20220103045407"},{name:"Bubble Wand",image:"https://static.wikia.nocookie.net/bee-swarm-simulator/images/1/16/Bubble_Wand.png/revision/latest?cb=20190403015841"},{name:"Porcelain Dipper",image:"https://static.wikia.nocookie.net/bee-swarm-simulator/images/e/e1/Porcelain_Dipper.png/revision/latest?cb=20240625063750"}],gear:[{name:"Bucko Guard",image:"https://static.wikia.nocookie.net/bee-swarm-simulator/images/2/22/Bucko_Guard.png/revision/latest/scale-to-width-down/160?cb=20190403020330"},{name:"Blue Port-O-Hive",image:"https://static.wikia.nocookie.net/bee-swarm-simulator/images/5/56/Blue_Port-O-Hive.png/revision/latest/scale-to-width-down/160?cb=20190405220756"}]},{name:"White Hive",color:"white",href:"#white-hive",icon:"https://static.wikia.nocookie.net/bee-swarm-simulator/images/5/50/Gummy_Mask.png/revision/latest/scale-to-width-down/408?cb=20210919012419",bees:F,tools:[{name:"Gummyballer",image:"https://static.wikia.nocookie.net/bee-swarm-simulator/images/c/c4/Gummyballer.png/revision/latest?cb=20211227045658"},{name:"Petal Wand",image:"https://static.wikia.nocookie.net/bee-swarm-simulator/images/d/d9/Petal_Wand.png/revision/latest?cb=20210402171049"},{name:"Spark Staff",image:"https://static.wikia.nocookie.net/bee-swarm-simulator/images/2/22/Spark_Staff.png/revision/latest/scale-to-width-down/98?cb=20190405220757"}],gear:[{name:"Coconut Canister",image:"https://static.wikia.nocookie.net/bee-swarm-simulator/images/9/9b/Coconut_Canister.png/revision/latest/scale-to-width-down/160?cb=20191006004936"},{name:"Petal Belt",image:"https://static.wikia.nocookie.net/bee-swarm-simulator/images/0/0d/Petal_Belt.png/revision/latest/scale-to-width-down/160?cb=20210402170808"}]},{name:"Mixed Hive",color:"mixed",href:"#mixed-hive",icon:"https://static.wikia.nocookie.net/bee-swarm-simulator/images/f/f0/Honey_Mask.png/revision/latest/scale-to-width-down/415?cb=20190403022334",bees:[...E,...F,...P],tools:[{name:"Magnet",image:"https://static.wikia.nocookie.net/bee-swarm-simulator/images/8/8c/Magnet.png/revision/latest/scale-to-width-down/113?cb=20200403234529"},{name:"Vacuum",image:"https://static.wikia.nocookie.net/bee-swarm-simulator/images/e/e1/Vacuum.png/revision/latest/scale-to-width-down/90?cb=20190402214642"},{name:"Port-O-Hive",image:"https://static.wikia.nocookie.net/bee-swarm-simulator/images/4/4a/Port-O-Hive.png/revision/latest/scale-to-width-down/160?cb=20190403021635"}],gear:[{name:"Mondo Belt Bag",image:"https://static.wikia.nocookie.net/bee-swarm-simulator/images/a/ad/Mondo_Belt_Bag.png/revision/latest/scale-to-width-down/160?cb=20190403020419"},{name:"Coconut Canister",image:"https://static.wikia.nocookie.net/bee-swarm-simulator/images/9/9b/Coconut_Canister.png/revision/latest/scale-to-width-down/160?cb=20191006004936"}]},{name:"Red Hive",color:"red",href:"#red-hive",icon:"https://static.wikia.nocookie.net/bee-swarm-simulator/images/9/96/Demon_Mask.png/revision/latest?cb=20210919013026",bees:P,tools:[{name:"Dark Scythe",image:"https://static.wikia.nocookie.net/bee-swarm-simulator/images/6/6b/Dark_Scythe.png/revision/latest?cb=20211226225244"},{name:"Scythe",image:"https://static.wikia.nocookie.net/bee-swarm-simulator/images/c/cd/Scythe.png/revision/latest/scale-to-width-down/138?cb=20190403020018"},{name:"Porcelain Dipper",image:"https://static.wikia.nocookie.net/bee-swarm-simulator/images/e/e1/Porcelain_Dipper.png/revision/latest?cb=20240625063750"}],gear:[{name:"Riley Guard",image:"https://static.wikia.nocookie.net/bee-swarm-simulator/images/f/f8/Riley_Guard.png/revision/latest/scale-to-width-down/160?cb=20190403020236"},{name:"Red Guard",image:"https://static.wikia.nocookie.net/bee-swarm-simulator/images/4/4c/Red_Guard.png/revision/latest/scale-to-width-down/160?cb=20190403020205"}]}],te=e=>`https://static.wikia.nocookie.net/bee-swarm-simulator/images/${e}`,n=(e,a,t,s)=>({name:e,color:a,image:te(t),description:s}),N=[{slug:"common",name:"Common",description:"The foundation of every growing hive.",color:"common"},{slug:"rare",name:"Rare",description:"Specialized bees with stronger abilities.",color:"rare"},{slug:"epic",name:"Epic",description:"Powerful bees with focused strengths.",color:"epic"},{slug:"legendary",name:"Legendary",description:"Exceptional bees with defining hive powers.",color:"legendary"},{slug:"mythic",name:"Mythic",description:"The rarest bees, built around unique mechanics.",color:"mythic"},{slug:"event",name:"Event",description:"Unique bees earned through special events and quests.",color:"event"}],C={common:[n("Basic Bee","colorless","7/76/Basic_Bee.png/revision/latest?cb=20200403233713","A balanced bee with no special color, making it useful in any early hive.")],rare:[n("Bomber Bee","colorless","7/7a/Bomber_Bee.png/revision/latest?cb=20200403233858","Bombs pollen from nearby flowers and helps convert pollen with Bomb tokens."),n("Brave Bee","colorless","1/10/Brave_Bee.png/revision/latest?cb=20200403234454","A sturdy bee that contributes attack and reliable red pollen."),n("Hasty Bee","colorless","b/be/Hasty_Bee.png/revision/latest?cb=20200403235822","Improves movement speed and keeps gathering routes moving quickly."),n("Looker Bee","colorless","5/5d/Looker_Bee.png/revision/latest?cb=20200403235630","Boosts critical chance and supports critical-focused hive builds."),n("Rad Bee","red","8/8d/Rad_Bee.png/revision/latest?cb=20200403235554","A red bee that gathers red pollen and adds attack power."),n("Rascal Bee","red","4/44/Rascal_Bee.png/revision/latest?cb=20200403235453","A red bee with strong early attack and red pollen output."),n("Stubborn Bee","colorless","3/3f/Stubborn_Bee.png/revision/latest?cb=20200403235346","Extends token duration and helps useful hive effects remain active.")],epic:[n("Bubble Bee","blue","f/fa/Bubble_Bee.png/revision/latest?cb=20200403235509","A blue bee that creates bubbles and gathers blue pollen efficiently."),n("Bucko Bee","blue","3/30/Bucko_Bee.png/revision/latest?cb=20200403235749","A blue attacker that boosts blue pollen and supports blue ability tokens."),n("Bumble Bee","blue","3/30/Bumble_Bee.png/revision/latest?cb=20200403235757","A blue bee that gathers extra pollen and contributes capacity support."),n("Cool Bee","blue","8/8b/Cool_Bee.png/revision/latest?cb=20200403235805","A reliable blue bee that gathers blue pollen and improves blue ability power."),n("Fire Bee","red","a/a4/Fire_Bee.png/revision/latest?cb=20200403235920","A red bee that creates flames and improves red pollen collection."),n("Frosty Bee","blue","f/fb/Frosty_Bee.png/revision/latest?cb=20200403235930","A blue bee that creates frosty tokens and gathers blue pollen."),n("Honey Bee","colorless","c/c3/Honey_Bee.png/revision/latest?cb=20200403235942","Produces Honey tokens and helps convert pollen into honey."),n("Rage Bee","red","7/7b/Rage_Bee.png/revision/latest?cb=20200404000023","A red bee that grants attack-focused Rage tokens to the hive."),n("Riley Bee","red","6/64/Riley_Bee.png/revision/latest?cb=20200404000004","A red bee that boosts red pollen and contributes strong red abilities."),n("Shocked Bee","blue","c/c0/Shocked_Bee.png/revision/latest?cb=20200404000019","A blue bee that grants haste and supports fast blue gathering.")],legendary:[n("Baby Bee","colorless","1/1f/Baby_Bee.png/revision/latest?cb=20200403235158","Creates Baby Love, increasing luck and improving the hive's gathering potential."),n("Carpenter Bee","colorless","7/75/Carpenter_Bee.png/revision/latest?cb=20200403235126","Creates Mark tokens and gathers pollen from marked flowers more effectively."),n("Demon Bee","red","8/84/Demon_Bee.png/revision/latest?cb=20200403234445","A red bee with high attack and strong red pollen abilities."),n("Diamond Bee","blue","0/0a/Diamond_Bee.png/revision/latest?cb=20200403234546","A blue bee that produces Honey tokens and gathers blue pollen efficiently."),n("Lion Bee","colorless","b/b3/Lion_Bee.png/revision/latest?cb=20200403234824","A powerful colorless attacker that brings balanced pollen and damage."),n("Music Bee","colorless","3/38/Music_Bee.png/revision/latest?cb=20200403234902","Creates Melody and Focus tokens that improve critical gathering."),n("Ninja Bee","blue","9/97/Ninja_Bee.png/revision/latest?cb=20200403235002","A fast blue bee that grants Haste and gathers blue pollen."),n("Shy Bee","red","e/e8/Shy_Bee.png/revision/latest?cb=20200403235237","A red bee that gathers red pollen and strengthens red ability tokens.")],mythic:[n("Buoyant Bee","blue","d/d7/Buoyant_Bee.png/revision/latest?cb=20230415203347","Creates balloons that store pollen and power up blue hive capacity."),n("Fuzzy Bee","colorless","c/c3/Fuzzy_Bee.png/revision/latest?cb=20230130022457","Pollinates nearby flowers and boosts their pollen while gathering."),n("Precise Bee","red","2/29/Precise_Bee.png/revision/latest?cb=20230415200607","Builds Precision stacks and creates precise marks for powerful red gathering."),n("Spicy Bee","red","4/43/Spicy_Bee.png/revision/latest?cb=20230417032558","Creates flame fuel and inferno abilities that amplify red pollen."),n("Tadpole Bee","blue","5/54/Tadpole_Bee.png/revision/latest?cb=20230417032602","Creates bubbles and frogs that support blue pollen and token generation."),n("Vector Bee","colorless","a/a6/Vector_Bee.png/revision/latest?cb=20230130024116","Creates Triangulate marks that reward precise movement and marked flowers.")],event:[n("Bear Bee","event","a/a9/Bear_Bee.png/revision/latest?cb=20190402203940","A friendly bee who transforms you into different bears!"),n("Cobalt Bee","blue","5/5c/Cobalt_Bee.png/revision/latest?cb=20200403235949","A superhero and defender of all things Blue! Together with Crimson Bee it works to unite bees of all colors."),n("Crimson Bee","red","5/5f/Crimson_Bee.png/revision/latest?cb=20200404000015","A superhero and defender of all things Red! Together with Cobalt Bee it works to unite bees of all colors."),n("Digital Bee","event","2/27/Digital_Bee.png/revision/latest?cb=20230415203844","A virtual bee with malfunctioning AI. It corrupts the game itself."),n("Festive Bee","event","2/23/Festive_Bee.png/revision/latest?cb=20200404000059","A jolly bee who loves giving gifts! It is purely motivated by the joy of others."),n("Gummy Bee","event","1/17/Gummy_Bee.png/revision/latest?cb=20200404000103","A squishy bee who is sweet as sugar. Covers flowers in goo to grant you bonus honey!"),n("Photon Bee","event","a/a6/Photon_Bee.png/revision/latest?cb=20200404000039","An entity made of pure light temporarily taking on the form of a bee."),n("Puppy Bee","event","0/01/Puppy_Bee.png/revision/latest?cb=20200404000127","A playful bee who only cares about two things, its tennis ball and you!"),n("Tabby Bee","event","b/b2/Tabby_Bee.png/revision/latest?cb=20200404000127","This affectionate bee was raised by cats. It becomes a better worker as it warms up to you."),n("Vicious Bee","event","1/1f/Vicious_Bee.png/revision/latest?cb=20200404000135","This cold-blooded bee takes great pleasure in inflicting pain."),n("Windy Bee","event","8/85/Windy_Bee.png/revision/latest?cb=20230415210459","An ethereal bee as powerful and unpredictable as the weather.")]},ae={"Basic Bee":["No ability token"],"Bomber Bee":["Bomb: collects pollen from nearby flowers"],"Brave Bee":["Red Boost: increases red pollen"],"Hasty Bee":["Haste: increases movement speed"],"Looker Bee":["Focus: increases critical chance"],"Rad Bee":["Red Boost: increases red pollen"],"Rascal Bee":["Red Bomb: collects red pollen"],"Stubborn Bee":["Token Link: links nearby tokens"],"Bubble Bee":["Bubble: collects pollen from nearby flowers"],"Bucko Bee":["Blue Boost: increases blue pollen"],"Bumble Bee":["Blue Boost: increases blue pollen"],"Cool Bee":["Blue Boost: increases blue pollen"],"Fire Bee":["Flame: burns nearby flowers for red pollen"],"Frosty Bee":["Blue Bomb: collects blue pollen"],"Honey Bee":["Honey: converts pollen into honey"],"Rage Bee":["Rage: increases bee attack"],"Riley Bee":["Red Boost: increases red pollen"],"Shocked Bee":["Haste: increases movement speed"],"Baby Bee":["Baby Love: increases loot luck"],"Carpenter Bee":["Mark: increases pollen from marked flowers"],"Demon Bee":["Red Bomb: collects red pollen"],"Diamond Bee":["Honey: converts pollen into honey"],"Lion Bee":["Token Link: links nearby tokens"],"Music Bee":["Melody: increases critical chance","Focus: increases critical chance"],"Ninja Bee":["Haste: increases movement speed"],"Shy Bee":["Red Boost: increases red pollen"],"Buoyant Bee":["Balloon: stores pollen and increases capacity"],"Fuzzy Bee":["Pollen Haze: pollinates nearby flowers"],"Precise Bee":["Precision: increases critical power","Target Practice: creates precise marks"],"Spicy Bee":["Flame Fuel: powers flames","Inferno: creates a field of flames"],"Tadpole Bee":["Bubble: collects pollen","Frog: summons a pollen-collecting frog"],"Vector Bee":["Triangulate: gathers from three marked flowers"],"Bear Bee":["Bear Morph: transforms the player into a bear"],"Cobalt Bee":["Blue Pulse: collects blue pollen and boosts blue pollen"],"Crimson Bee":["Red Pulse: collects red pollen and boosts red pollen"],"Digital Bee":["Code Mark: copies and amplifies enemy abilities"],"Festive Bee":["Festive Gift: grants a random gift effect"],"Gummy Bee":["Goo: covers flowers and grants bonus honey"],"Photon Bee":["Beamstorm: fires a beam that collects pollen"],"Puppy Bee":["Fetch: sends the bee to fetch a tennis ball"],"Tabby Bee":["Scratch: collects pollen in a cone","Tabby Love: increases Tabby Bee pollen"],"Vicious Bee":["Impale: summons spikes that damage enemies"],"Windy Bee":["Tornado: gathers pollen and grants Wind Blessing"]},oe={"Basic Bee":"x1.2 pollen","Bomber Bee":"+15% bomb pollen","Brave Bee":"+5% bee attack","Hasty Bee":"+1 player movespeed","Looker Bee":"+25% critical power","Rad Bee":"+15% red pollen","Rascal Bee":"+15% red bomb pollen","Stubborn Bee":"+20% token duration","Bubble Bee":"+15% bubble pollen","Bucko Bee":"+20% blue pollen","Bumble Bee":"+15% capacity","Cool Bee":"+15% blue pollen","Fire Bee":"+15% flame pollen","Frosty Bee":"+15% blue pollen","Honey Bee":"+25% honey from tokens","Rage Bee":"+15% bee attack","Riley Bee":"+20% red pollen","Shocked Bee":"+1 player movespeed","Baby Bee":"+25% Baby Love luck","Carpenter Bee":"+25% mark duration","Demon Bee":"+15% red pollen","Diamond Bee":"+15% capacity","Lion Bee":"+5% bee attack","Music Bee":"+25% melody duration","Ninja Bee":"+15% blue pollen","Shy Bee":"+15% red pollen","Buoyant Bee":"+15% balloon capacity","Fuzzy Bee":"+15% pollen","Precise Bee":"+15% super-crit chance","Spicy Bee":"+15% flame duration","Tadpole Bee":"+15% bubble duration","Vector Bee":"+15% mark duration","Bear Bee":"+10% all pollen","Cobalt Bee":"+15% blue pollen","Crimson Bee":"+15% red pollen","Digital Bee":"+1% super-crit chance","Festive Bee":"+15% convert rate","Gummy Bee":"+1.5x goo conversion","Photon Bee":"+5% instant conversion","Puppy Bee":"+20% bond from treats","Tabby Bee":"+50% Tabby Love pollen","Vicious Bee":"+15% bee attack","Windy Bee":"+15% white pollen"},V=[],se={"Basic Bee":"Basic Bee has no special active ability token, but it remains one of the most dependable starter bees in a growing hive. Its simple, balanced profile makes it easy to build around early in the game, especially when a player is still deciding on a color focus. It is obtained automatically from the starter hive and does not require any special steps to unlock.","Bomber Bee":"Bomber Bee fires bombs that collect pollen from nearby flowers and help clear clusters quickly. This makes it especially effective while leveling early red and mixed hives that need burst collection. It is obtained from the Basic Egg and later through normal hive progression, making it a natural early-game pickup.","Brave Bee":"Brave Bee focuses on reliable attack support and helps a hive convert more red pollen during combat and field runs. Its strength is consistency, giving early and mid-game players a dependable source of damage and collection. Brave Bee is acquired by hatching it from the Basic Egg or by progressing through the early hive egg pool.","Hasty Bee":"Hasty Bee gives a speed boost through its Haste effect, helping the player move between flowers and gather more quickly. It improves route efficiency and makes the player much less likely to waste time while farming. Hasty Bee is obtained through the usual early-game hive progression and egg hatches.","Looker Bee":"Looker Bee strengthens critical-hit chance and makes the hive more efficient when focused on crit-heavy pollen gathering. The extra criticals help turn a steady route into a noticeably stronger collection cycle. It is obtained through early progression and standard bee hatching, usually before players reach the more specialized event bees.","Rad Bee":"Rad Bee boosts red pollen collection and increases the output of red-hive gathering routes. Its main value is how it steadily supports red-field farming without requiring much setup. Rad Bee is obtained through the standard egg pool and is commonly found as a natural red bee progression step.","Rascal Bee":"Rascal Bee uses a red-burst effect that gathers pollen from nearby flowers and helps a hive build momentum rapidly. It is useful in early red setups that need a strong area-collection tool before more specialized bees are available. Rascal Bee is unlocked through regular red bee progression and egg hatches.","Stubborn Bee":"Stubborn Bee links nearby ability tokens together so the player can pick up more useful effects from the same area. This makes it highly valuable in routes where token collection matters just as much as flower gathering. Stubborn Bee is obtained through the standard bee pool as a durable early or mid-game support option.","Bubble Bee":"Bubble Bee creates bubble effects that pull pollen from nearby flowers and provide steady blue-field support. It is especially useful for a player who wants a clean, consistent blue pollen route without relying on heavy token setup. Bubble Bee is obtained through normal blue bee progression and regular hive hatching.","Bucko Bee":"Bucko Bee boosts blue pollen output and helps blue hives produce more efficient field runs. It works well as a support bee in blue-focused setups because it strengthens the collection flow rather than relying on flashy, temporary effects. Bucko Bee is unlocked through standard blue bee progression and egg hatches.","Bumble Bee":"Bumble Bee contributes capacity and blue pollen support, which makes it especially good for players who need to gather more before converting. It helps a blue hive stay efficient without forcing the player to change the whole route. Bumble Bee is obtained through the blue bee progression track and standard hive hatching.","Cool Bee":"Cool Bee improves blue pollen collection and provides steady support in blue-heavy field routes. Its value comes from consistency, helping players keep momentum during long farming sessions. Cool Bee is obtained through normal blue bee progression and is a common mid-game blue bee.","Fire Bee":"Fire Bee creates flames that can burn flowers and collect red pollen over a wider area. This makes it useful for red-field farming where a stronger area effect helps the player gather faster. Fire Bee is acquired through the red bee progression track and naturally appears in the common hive egg pool.","Frosty Bee":"Frosty Bee uses a blue-burst effect to gather pollen from nearby blooms and supports blue hive efficiency in the middle of a run. It is a good early-to-mid-game support bee for players who want cleaner blue collection while moving through a field. Frosty Bee is obtained through standard blue bee progression and hatching.","Honey Bee":"Honey Bee converts a portion of gathered pollen into honey, making it a major contributor to a hive that needs steady conversion. That conversion helps the player maintain growth and resource flow without overrelying on pure pollen collection. Honey Bee is obtained through the hive progression system and becomes a staple blue or neutral support bee in many builds.","Rage Bee":"Rage Bee increases bee attack and helps the hive more effectively deal with enemies and dangerous field content. It is especially useful when a player wants a stronger combat-focused setup without sacrificing collection efficiency. Rage Bee is acquired through normal hive progression and is tied to the red bee progression path.","Riley Bee":"Riley Bee adds steady red pollen support and improves the output of a red-focused route. It is one of the more reliable early color-specific bees because its effect is simple and consistent rather than extremely specialized. Riley Bee is obtained through standard red bee progression and standard egg hatches.","Shocked Bee":"Shocked Bee provides a Haste-style boost, which improves movement and makes it easier to keep a route moving cleanly. This helps players regain efficiency during long farm loops and reduces downtime between flowers. Shocked Bee is obtained as part of the normal blue bee progression cycle.","Baby Bee":"Baby Bee gives Baby Love, which raises loot luck and improves the quality of rewards obtained during a run. It is most valuable for players trying to improve their reward efficiency while farming for upgrades and special drops. Baby Bee is usually acquired through the standard bee progression system and is a key early mid-game support bee.","Carpenter Bee":"Carpenter Bee creates Mark effects that improve pollen from marked flowers and reward informed route planning. It works best when a player is moving through a field with strong marked targets instead of relying purely on random collecting. Carpenter Bee is obtained through normal hive progression and is commonly used in colorless or utility builds.","Demon Bee":"Demon Bee combines a powerful red-field effect with strong attack support, making it excellent for combat and red pollen collection. It is especially useful when a player is trying to maintain high output during a difficult field run. Demon Bee is acquired through the red bee progression path and later hive advancement.","Diamond Bee":"Diamond Bee supports blue pollen collection and converts gathered pollen into honey through a more efficient flow. It is a strong mid-game choice for players who want better conversion and a steady blue collection pace. Diamond Bee is obtained through the normal progression cycle and regular hatching.","Lion Bee":"Lion Bee is a strong colorless attacker that gives the hive a balanced mix of combat value and collection support. It works well in mixed or neutral builds that need a reliable offensive option without giving up extra pollen. Lion Bee is obtained through the later hive progression track and is a classic legendary power bee.","Music Bee":"Music Bee creates Melody and Focus effects that improve critical chance and collection quality in a run. Its main strength is how it amplifies critical-based routes and turns a steady route into a much stronger one. Music Bee is obtained through normal progression and is typically considered a highly valuable legendary support bee.","Ninja Bee":"Ninja Bee gives a Haste-like boost while also helping blue hives maintain good collection flow. It is especially efficient for fast resource routes where the player is moving constantly between flowers. Ninja Bee is obtained through standard blue and legendary bee progression.","Shy Bee":"Shy Bee improves red pollen collection and supports red-hive routes that need reliable output. Its value is in consistency, making it a useful bee for players who want a smoother red collection cycle without heavy complexity. Shy Bee is obtained through regular red bee progression and standard hatching.","Buoyant Bee":"Buoyant Bee makes balloons that store pollen and increase the hive’s holding capacity before conversion. This helps players collect more in a single route and reduces the need to convert too early. Buoyant Bee is acquired through late-game progression and special hive unlocks.","Fuzzy Bee":"Fuzzy Bee pollinates nearby flowers and increases the amount of pollen available from the surrounding area. It works best in higher-level routes where a player wants more efficient field cleanup and stronger nearby collection. Fuzzy Bee is obtained through mid-to-late game progression and is generally treated as a mythic support bee.","Precise Bee":"Precise Bee builds Precision and creates targeted marks that improve the value of careful movement through the field. It rewards players who are intentional about route planning and position themselves around marked bloom clusters. Precise Bee is acquired through progression and is a staple mythic choice for high-output red or all-round builds.","Spicy Bee":"Spicy Bee creates flame-driven effects that spread through a cluster and help a hive gather heavier amounts of red pollen. It is especially good for intense field runs where a wide area effect matters more than a one-flower burst. Spicy Bee is obtained via the mythic bee progression path and is considered a high-power red bee.","Tadpole Bee":"Tadpole Bee creates bubbles and frog-based support that snap up pollen while the player moves through the field. It provides strong blue-area efficiency and helps the hive sustain with good collection pacing. Tadpole Bee is unlocked through the mythic progression track and advanced hive progression.","Vector Bee":"Vector Bee creates triangulated marks and rewards route efficiency by collecting from multiple linked flowers in a coordinated pattern. It is a favorite for players who like precise movement and want a stronger connection between route design and value. Vector Bee is obtained through mythic progression and advanced hive unlocking.","Bear Bee":"Bear Bee uses Bear Morph to transform the player into a bear form and gives the hive a memorable, highly thematic movement and collection effect. The transformation changes how the player interacts with the field and can make gathering feel much more aggressive. Bear Bee is obtained through the event progression and specific event quest or celebration conditions associated with the bee.","Cobalt Bee":"Cobalt Bee sends out a blue pulse that gathers blue pollen and supports the hive’s blue-field efficiency. It is a strong event bee because it gives a direct and noticeable boost to blue pollen routes without requiring a complicated setup. Cobalt Bee is obtained through the event bee system and is tied to the blue event bee progression.","Crimson Bee":"Crimson Bee sends out a red pulse that brings in red pollen quickly and helps maintain red hive productivity. It is most effective in red-focused runs where the player wants a fast, strong burst of collection. Crimson Bee is acquired through event bee progression and special event conditions.","Digital Bee":"Digital Bee uses code-based effects and corrupted field logic to amplify the hive’s ability output in a very unusual way. It rewards players who understand unusual route patterns and can exploit the field disruption to gain more value. Digital Bee is obtained through unique event or special-event progression and is tied to the Digital event bee system.","Festive Bee":"Festive Bee creates celebratory gains and random gift effects that add a temporary benefit to the player while farming. Its charm lies in utility and surprising boosts rather than a single hard-coded stat increase. Festive Bee is acquired through seasonal or special event progression, which is why it belongs in the event bee category.","Gummy Bee":"Gummy Bee covers flowers with goo and creates a sticky layer that boosts honey gains and collection value. It is powerful for players focused on conversion and want a more efficient way to convert their pollen into honey. Gummy Bee is obtained through event progression and is a classic event bee with a strong utility identity.","Photon Bee":"Photon Bee fires a beam that sweeps across flowers and instantly gathers pollen from its path. Its strength is the wide area coverage and quick value gained during a route, which makes it excellent for sweeping a field quickly. Photon Bee is obtained through the event bee system and is one of the more unusual special bees in the game.","Puppy Bee":"Puppy Bee chases its ball and returns it to the player to trigger a collectible effect that supports gathering momentum. It is a playful but useful event bee that brings a small burst of value to a route, especially when players want a bright, active support role. Puppy Bee is obtained through the event bee progression and is usually tied to a specific seasonal or collection event.","Tabby Bee":"Tabby Bee uses Scratch to collect pollen in a cone and improves its value through Tabby Love as it gains trust. It is a personality-heavy event bee that delivers solid utility in collection and can become increasingly effective as the player builds the bond. Tabby Bee is obtained through the event bee progression system and benefits from the player maintaining that event relationship.","Vicious Bee":"Vicious Bee uses Impale to create spikes that damage enemies and give the hive a direct combat advantage. It is one of the most recognizable event bees because it turns the hive into a stronger combat force while still contributing a consistent battlefield effect. Vicious Bee is obtained through the event bee system and is associated with special event or challenge conditions.","Windy Bee":"Windy Bee creates a tornado effect that gathers pollen and grants Wind Blessing to improve the surrounding field run. It feels very dynamic and is valuable in routes where players want both large-scale collection and a little extra atmosphere or power. Windy Bee is obtained through the event bee system and special event progression."},ie={"Basic Bee":"Unlocked automatically with the starter hive and does not require any special step.","Bomber Bee":"Obtained through regular early-game hive progression and standard bee hatching.","Brave Bee":"Unlocked through normal early-game bee progression and egg hatches.","Hasty Bee":"Obtained through the regular early bee progression track.","Looker Bee":"Unlocked through the normal progression system and standard bee hatching.","Rad Bee":"Obtained through regular red bee progression and hive egg hatches.","Rascal Bee":"Unlocked through the red bee progression track and normal game progression.","Stubborn Bee":"Obtained through the standard progression pool and general bee hatching.","Bubble Bee":"Unlocked through standard blue bee progression and egg hatches.","Bucko Bee":"Obtained through regular blue bee progression and standard hatching.","Bumble Bee":"Unlocked in the normal blue bee progression system.","Cool Bee":"Obtained through regular blue bee progression and standard hatching.","Fire Bee":"Unlocked through the red progression path and normal hive hatching.","Frosty Bee":"Obtained through the standard blue bee progression route.","Honey Bee":"Unlocked through general progression and standard bee hatching.","Rage Bee":"Obtained through the red bee progression track and hive progression.","Riley Bee":"Unlocked through the regular red bee progression system.","Shocked Bee":"Obtained through standard blue bee progression and standard hatching.","Baby Bee":"Unlocked through standard legendary bee progression and normal hive growth.","Carpenter Bee":"Obtained through normal progression and bee hatching.","Demon Bee":"Unlocked through the red progression path and deeper hive progression.","Diamond Bee":"Obtained through regular blue hive progression and standard hatching.","Lion Bee":"Unlocked through the legendary bee progression track and later hive progression.","Music Bee":"Obtained through standard progression and legendary bee hatching.","Ninja Bee":"Unlocked through the blue bee progression track and later hive advancement.","Shy Bee":"Obtained through the normal red bee progression cycle and standard hatching.","Buoyant Bee":"Unlocked in later progression as a mythic bee and requires regular hive advancement.","Fuzzy Bee":"Obtained through the mythic bee progression track and higher-tier hive progression.","Precise Bee":"Unlocked through later progression and is tied to mythic bee advancement.","Spicy Bee":"Obtained through the mythic red bee progression track and higher-tier hive growth.","Tadpole Bee":"Unlocked through the mythic blue bee progression path.","Vector Bee":"Obtained through advanced mythic progression and higher-tier hive unlocking.","Bear Bee":"Obtained through special event progression associated with the Bear Bee event system.","Cobalt Bee":"Unlocked through the event bee system and blue event progression.","Crimson Bee":"Unlocked through the event bee system and red event progression.","Digital Bee":"Obtained through the Digital event progression and special event conditions.","Festive Bee":"Unlocked through festive or seasonal event progression.","Gummy Bee":"Obtained through the event bee system and event progression.","Photon Bee":"Unlocked through event progression and the Photon Bee event route.","Puppy Bee":"Obtained through the event bee system and its seasonal or special event unlock.","Tabby Bee":"Unlocked through the event bee progression and the Tabby Bee relationship/event system.","Vicious Bee":"Obtained through the event bee system and event challenge progression.","Windy Bee":"Unlocked through the event bee system and the Windy Bee event progression cycle."},ne={"Basic Bee":"+20% pollen","Bomber Bee":"+15% bomb pollen","Brave Bee":"+5% bee attack","Hasty Bee":"+15% haste token duration","Looker Bee":"+25% critical power","Rad Bee":"+15% red pollen","Rascal Bee":"+15% red bomb pollen","Stubborn Bee":"+20% token duration","Bubble Bee":"+15% bubble pollen","Bucko Bee":"+20% blue pollen","Bumble Bee":"+15% capacity","Cool Bee":"+15% blue pollen","Fire Bee":"+15% flame pollen","Frosty Bee":"+15% blue pollen","Honey Bee":"+25% honey from tokens","Rage Bee":"+15% bee attack","Riley Bee":"+20% red pollen","Shocked Bee":"+15% shocked pollen","Baby Bee":"+25% Baby Love loot luck","Carpenter Bee":"+25% mark duration","Demon Bee":"+15% red pollen","Diamond Bee":"+15% capacity","Lion Bee":"+5% bee attack","Music Bee":"+25% melody duration","Ninja Bee":"+15% blue pollen","Shy Bee":"+15% red pollen","Buoyant Bee":"+15% balloon capacity","Fuzzy Bee":"+15% pollen","Precise Bee":"+15% super-crit chance","Spicy Bee":"+15% flame duration","Tadpole Bee":"+15% bubble duration","Vector Bee":"+15% mark duration","Bear Bee":"+10% all pollen","Cobalt Bee":"+15% blue pollen","Crimson Bee":"+15% red pollen","Digital Bee":"+1% super-crit chance","Festive Bee":"+15% convert rate","Gummy Bee":"+1.5x goo conversion","Photon Bee":"+5% instant conversion","Puppy Bee":"+20% bond from treats","Tabby Bee":"+50% Tabby Love pollen","Vicious Bee":"+15% bee attack","Windy Bee":"+15% white pollen"},re={"Bear Bee":"Gifted Bear Morph has a 20% chance to transform the player into a rare bear. Mother Bear gives x2.5 pollen and x1.5 bee-gather pollen; Science Bear grants +1 convert rate and +1% ability rate.","Digital Bee":"Gifted Digital Bee unlocks Map Corruption: it corrupts a random field for all players for 3 minutes, plus 15 seconds per bee level. Drives increase the corruption amount, up to 300."};Object.entries(C).forEach(([e,a])=>a.forEach(t=>{t.rarity=e,t.slug=t.name.toLowerCase().replace(/ bee$/,"").replace(/[^a-z0-9]+/g,"-"),t.tokens=ae[t.name]||["Ability token information is maintained on the BSS Wiki."],t.giftedBonus=oe[t.name]||"Gifted bonus information is maintained on the BSS Wiki.",t.ability=se[t.name]||t.description,t.obtainment=ie[t.name]||"This bee is obtained through normal progression and is discussed on the BSS Wiki.",t.giftedAbility=ne[t.name]||"Gifted ability information is maintained on the BSS Wiki.",t.giftedSpecialAbility=re[t.name]||null,t.wikiUrl=`https://bee-swarm-simulator.fandom.com/wiki/${t.name.replace(/ /g,"_")}`}));const le=e=>`/images/mobs/${e.toLowerCase().replace(/[^a-z0-9]+/g,"-")}.png`,y=(e,a,t,s,o,l)=>({name:e,slug:e.toLowerCase().replace(/[^a-z0-9]+/g,"-"),image:le(e),type:a,description:t,behavior:s,drops:o,respawn:l}),x=[y("Ladybug","Common enemy","A small red enemy found across early and mid-game fields.","It walks toward the player and attacks at close range.","Treats, honey, and field loot","5 minutes"),y("Rhino Beetle","Common enemy","A sturdy early-game enemy with a horn charge.","It charges and bumps the player while defending its field.","Treats, honey, and field loot","5 minutes"),y("Spider","Common enemy","A white enemy that guards the Spider Field.","It moves quickly and attacks the player from close range.","Treats, honey, and field loot","10 minutes"),y("Scorpion","Common enemy","A red enemy that guards the Rose Field and attacks aggressively.","It chases the player and uses its stinger at close range.","Treats, honey, and field loot","5 minutes"),y("Mantis","Common enemy","A green enemy found in several fields throughout the mountain.","It attacks with sweeping strikes and can pressure the player at close range.","Treats, honey, and field loot","10 minutes"),y("Werewolf","Common enemy","A powerful enemy found in the Werewolf Cave.","It pursues the player and deals heavy melee damage.","Treats, honey, and field loot","10 minutes"),y("King Beetle","Boss","A recurring boss hidden beneath the Clover Field.","It has high health, attacks nearby players, and rewards a successful defeat with boss loot.","Treats, honey, amulets, and boss loot","24 hours"),y("Tunnel Bear","Boss","A major boss found in the Tunnel beneath the Clover Field.","It attacks with strong close-range hits and has a large health pool.","Treats, honey, tickets, and boss loot","48 hours"),y("Stump Snail","Boss","A huge boss that occupies the Stump Field.","It has enormous health and remains in the field until defeated.","Treats, honey, amulets, and boss loot","96 hours"),y("Coconut Crab","Boss","A high-level boss that guards Coconut Field.","It attacks with claws and coconut projectiles while defending its field.","Treats, honey, tropical loot, and boss loot","36 hours"),y("Vicious Bee","Event boss","A rare event enemy that can appear in several fields.","It flies around the field, attacks with spikes, and drops valuable stingers when defeated.","Stingers, honey, treats, and rare loot","30 minutes"),y("Stick Bug","Boss challenge","A challenge boss that leads the player through multiple fields.","Its challenge has stages, changing locations and difficulty as the player progresses.","Amulets, honey, tokens, and challenge rewards","Challenge cooldown varies")],ce={Ladybug:{overview:"Ladybugs are common red mobs that protect several early and mid-game fields. They are approachable targets for collecting early battle rewards and building combat progress.",behavior:"A Ladybug walks toward the player and attacks at close range. Its predictable movement makes it a useful first combat target for a developing hive.",drops:"Ladybugs always provide their normal battle reward, honey, and a token circle after defeat. Their possible Ticket drop has a 2% base chance, and Loot Luck increases that drop chance.",luck:"At 0% Loot Luck the Ticket chance is 2%. At +100% Loot Luck, the wiki formula gives two rolls, making the chance 3.96%.",respawn:"5 minutes (4 minutes 15 seconds with Gifted Vicious Bee)"},"Rhino Beetle":{overview:"Rhino Beetles are sturdy early-game mobs found in several fields. They are useful for battle points, honey, and early blue-field loot.",behavior:"A Rhino Beetle charges and bumps the player while defending its field. Staying mobile helps the hive avoid its direct attack.",drops:"Rhino Beetles provide battle rewards, honey, and possible Tickets, Blueberries, and Gumdrops. The Ticket drop has a 2% base chance, while the other possible drops are affected by Loot Luck.",luck:"At 0% Loot Luck the Ticket chance is 2%, becoming 3.96% at +100% Loot Luck. The wiki lists the other item chances as Loot Luck affected without giving one fixed percentage.",respawn:"5 minutes (4 minutes 15 seconds with Gifted Vicious Bee)"},Spider:{overview:"The Spider guards Spider Field and is one of the first mobs with a longer respawn cycle. Defeating it provides stronger battle rewards than the earliest field mobs.",behavior:"The Spider moves quickly and attacks at close range. It can chase the player beyond its field, so movement and bee attack both matter.",drops:"The Spider can drop Tickets and Gumdrops in addition to its normal honey and battle rewards. Its Ticket drop has a 25% base chance and is affected by Loot Luck.",luck:"At 0% Loot Luck the Ticket chance is 25%. At +100% Loot Luck, the two-roll chance is 43.75% using the wiki Loot Luck formula.",respawn:"30 minutes (25 minutes 30 seconds with Gifted Vicious Bee)"},Scorpion:{overview:"Scorpions are red mobs that guard Rose Field and reward players with red-field materials. They are more dangerous than Ladybugs because they combine aggressive pursuit with a longer timer.",behavior:"A Scorpion chases the player and attacks with its stinger at close range. Red pollen and attack-focused bees help clear it efficiently.",drops:"Scorpions guarantee battle points and honey, then can provide Tickets, Gumdrops, and Strawberries. The Ticket chance is 2/15, or about 13.33%, while Loot Luck affects the item drops marked by the wiki.",luck:"At 0% Loot Luck the Ticket chance is about 13.33%. At +100% Loot Luck, two independent rolls would give about 24.89% if that drop is treated as Loot Luck affected.",respawn:"20 minutes (17 minutes with Gifted Vicious Bee)"},Mantis:{overview:"Mantis mobs appear in multiple mountain fields and offer useful battle rewards. They are a mid-level target that can be farmed repeatedly while traveling between fields.",behavior:"A Mantis uses sweeping close-range attacks and pressures players who stand still. Keeping bees attacking while moving around it reduces the danger.",drops:"Mantis mobs provide normal honey and battle rewards, with possible Tickets and Gumdrops. The Ticket drop has a 20% base chance and is increased by Loot Luck.",luck:"At 0% Loot Luck the Ticket chance is 20%. At +100% Loot Luck, the two-roll chance is 36% using the wiki formula.",respawn:"20 minutes (17 minutes with Gifted Vicious Bee)"},Werewolf:{overview:"The Werewolf is a strong cave mob with a larger reward table than common field enemies. It is a good target for players who can handle heavier melee damage.",behavior:"The Werewolf pursues the player and deals heavy close-range damage. Its cave location limits room to maneuver, so attack power and quick collection are valuable.",drops:"Werewolves provide honey and battle rewards, with possible Tickets, Gumdrops, and Silver Eggs. The Ticket drop has a 50% base chance and is affected by Loot Luck.",luck:"At 0% Loot Luck the Ticket chance is 50%. At +100% Loot Luck, the two-roll chance becomes 75%.",respawn:"1 hour (51 minutes with Gifted Vicious Bee)"},"King Beetle":{overview:"King Beetle is a boss hidden beneath Clover Field and offers one of the earliest boss encounters. Its defeat can provide a King Beetle Amulet as well as a larger reward payout.",behavior:"King Beetle has high health and attacks players near the center of its lair. Bees with strong attack shorten the fight and reduce the time spent waiting for the next cycle.",drops:"King Beetle always gives its battle reward, honey, and other possible loot. The King Beetle Amulet has a fixed 1/7 chance, about 14%, and the wiki states Loot Luck does not improve that amulet chance.",luck:"At 0% Loot Luck the amulet chance is about 14%. With Loot Luck the amulet remains about 14%, while other eligible drops can become more likely.",respawn:"24 hours (20 hours 24 minutes with Gifted Vicious Bee)"},"Tunnel Bear":{overview:"Tunnel Bear is a boss located in the tunnel beneath the early mountain area. It has a large health pool and gives a substantial reward table when defeated.",behavior:"Tunnel Bear attacks with strong close-range hits while the player fights through its tunnel. Its narrow arena makes sustained bee damage and careful movement important.",drops:"Tunnel Bear drops honey, treats, Gumdrops, Tickets, and other possible boss rewards. The wiki describes the possible reward quantities as Loot Luck affected rather than assigning one universal percentage to every item.",luck:"The base chance differs by item and reward table, so there is no single Tunnel Bear drop percentage. Loot Luck adds rolls according to the wiki formula, while guaranteed rewards remain guaranteed.",respawn:"48 hours (40 hours 48 minutes with Gifted Vicious Bee)"},"Stump Snail":{overview:"Stump Snail is a huge boss that occupies Stump Field until defeated. Its enormous health makes it a long-term combat goal and a major source of rewards.",behavior:"The Snail remains in its field and has extremely high health. Players usually damage it over repeated visits rather than finishing the fight in one short session.",drops:"Stump Snail guarantees an amulet and is the only mob that guarantees Glue, alongside honey, Gumdrops, and other possible loot. The wiki lists additional item chances through its reward table rather than one universal drop percentage.",luck:"Guaranteed amulet and Glue remain guaranteed at 0% and with Loot Luck. Other eligible drops use their table chances and become more likely when Loot Luck grants extra rolls.",respawn:"96 hours (81 hours 36 minutes with Gifted Vicious Bee)"},"Coconut Crab":{overview:"Coconut Crab is a high-level boss guarding Coconut Field. Its reward quality and quantity can depend on how quickly the player defeats it.",behavior:"The Crab attacks with claws and coconut projectiles while defending its field. Players must balance movement, damage, and token collection because the fight can punish standing in one place.",drops:"Coconut Crab provides honey, treats, Gumdrops, tropical materials, and other boss rewards. The wiki notes that some reward quality and quantity depends on defeat speed, while eligible drops are also influenced by Loot Luck.",luck:"There is no single public percentage for the full Coconut Crab reward table. Loot Luck improves eligible drop rolls, but it does not replace the separate effect of defeating the Crab quickly.",respawn:"36 hours (30 hours 36 minutes with Gifted Vicious Bee)"},"Vicious Bee":{overview:"Vicious Bee is a rare event boss that can appear in several fields during the night. A Stinger appearing in a field is the clue that a Vicious Bee has spawned there, and defeating it can provide valuable Stingers and rare loot.",behavior:"Vicious Bee flies around the field and attacks with spikes, so precise positioning and strong bee attack are important. Its level, health, and damage are not fixed; they vary according to the field where it appears.",drops:"Vicious Bee drops Stingers, honey, treats, and other rare loot after defeat. Loot Luck improves eligible item rolls, but it does not guarantee a Stinger and the exact reward chances depend on the drop table.",luck:"The wiki does not give one universal percentage for every Vicious Bee drop. At higher Loot Luck, eligible drops receive extra rolls using 1 - ((1 - base chance) ^ luck), while guaranteed rewards remain unchanged.",respawn:"No fixed respawn timer; check fields at night for the Stinger spawn clue",fieldScaling:"Vicious Bee level, health, and damage vary by spawn field. A field-specific encounter can therefore be much easier or harder than another Vicious Bee encounter.",giftedRespawn:"Gifted Vicious Bee grants -15% Mob Respawn Time to applicable mobs; it does not create a fixed Vicious Bee respawn countdown."},"Stick Bug":{overview:"Stick Bug is a multi-stage boss challenge rather than a simple field mob. Its difficulty and rewards change as the challenge moves through different fields.",behavior:"Stick Bug progresses through stages and changes locations as the challenge continues. Players need coordinated damage and movement to keep up with the changing arena.",drops:"Stick Bug can award amulets, honey, tokens, and challenge rewards after the run. Its reward quality depends on the challenge result, so the wiki does not provide one universal drop percentage for every reward.",luck:"Because Stick Bug rewards are tied to challenge performance and tables, there is no single base-versus-Loot-Luck percentage. Loot Luck affects eligible item rolls when the reward table allows it, but it does not replace score-based rewards.",respawn:"Challenge cooldown varies"}};x.forEach(e=>Object.assign(e,ce[e.name]));const de=e=>x.find(a=>a.slug===e),B=[{name:"Revolution Macro",slug:"revolution",developer:"Liam",category:["Macro","AI"],description:"A cross-platform Bee Swarm Simulator macro with AI-assisted pathfinding and gathering.",longDescription:["Revolution Macro is a solo project created by Liam. It is designed around a modern macro experience for Windows and macOS.","Its public feature list includes AI-assisted stinger hopping, AI pathfinding, configurable gathering, and dispenser collection."],whatItDoes:"Revolution automates gathering and movement in Bee Swarm Simulator. Its AI pathfinding is designed to move between tasks without requiring a reset, while its gathering and dispenser tools handle recurring session tasks.",rank:1,rating:5,ratingReason:"Highly rated for its feature set, cross-platform support, AI-assisted functionality, and overall macro experience.",ratingFactors:{reliability:null,features:5,easeOfUse:null,updates:null,documentation:4,compatibility:5,communitySupport:null},status:"Active",version:"",lastUpdated:"",lastVerified:"2026-08-27",platforms:["Windows","macOS"],features:["AI stinger hop","AI pathfinding","Field gathering","Dispenser collection"],supportedFields:[],requirements:["Windows or macOS","Bee Swarm Simulator"],limitations:[],knownIssues:[]